private fun setupAlarm(triggerAtMillis: Long, operation: PendingIntent) {
  if (Build.VERSION.SDK_INT < Build.VERSION_CODES.S || alarmManager.canScheduleExactAlarms()) {
    AlarmManagerCompat.setExactAndAllowWhileIdle(alarmManager, AlarmManager.RTC_WAKEUP, triggerAtMillis, operation)
  } else {
    AlarmManagerCompat.setAndAllowWhileIdle(alarmManager, AlarmManager.RTC_WAKEUP, triggerAtMillis, operation)
  }
}

// Reproducción mía de cuántas alarmas deja una pasada de reprogramarAvisos.
// Constantes leídas en src/util/avisos.ts (commit 25e08fa). Es una cuenta, no el código real.
function alarmas({ eventos, ocurrencias = 6, nube = 0, copasMarcadas = 0, recordatorio = true, hoyHecho = false }) {
  const deEventos = eventos * ocurrencias;      // proximas(e, ahora, 6) por evento con aviso
  const deNube = Math.min(nube, 20);            // proximosNube(...).slice(0, 20)
  const deCopas = copasMarcadas * 2;            // la noche antes y la mañana del día
  const diario = recordatorio ? (hoyHecho ? 6 : 7) : 0;
  return deEventos + deNube + deCopas + diario;
}
